import pathlib,json,hashlib,collections
import openpyxl
R=pathlib.Path('__WORKSPACE_ROOT__');W=R/'work/external_convergence_20260926';O=R/'outputs/external_convergence_20260926';W.mkdir(exist_ok=True);O.mkdir(exist_ok=True)
src=R/'outputs/external_benchmark_20260926/ASD_External_Evidence_Benchmark_2026-09-26.xlsx'
digest=hashlib.sha256(src.read_bytes()).hexdigest();wb=openpyxl.load_workbook(src,read_only=True,data_only=True)
def read(s):
 it=wb[s].values;h=next(it);return [dict(zip(h,r)) for r in it if any(v is not None for v in r)]
matrix=read('External_Evidence_Matrix');regional=read('ExternalEvidence_17q21.31');ov=[r for r in read('Overlap_summary') if r['TWAS_set']=='Union']
assert len(matrix)==152 and len({r['Ensembl_ID'] for r in matrix})==152
cols=['Huang2021_TWAS','Matoba2020_HMAGMA','Gandal2022_whole_cortex_DGE']
def count(r):return sum(bool(r[c]) for c in cols)
def walker(r):return bool(r['Walker2019_prenatal_expression'] or r['Walker2019_prenatal_splicing'])
allrows=[]
for r in matrix:
 a={k:r[k] for k in ['Gene','Ensembl_ID','JTI_significant','FUSION_significant','JTI_FUSION_shared']}
 a.update(dict(zip(['Huang2021_support','Matoba2020_support','Gandal2022_support'],[r[c] for c in cols])))
 a.update({k:r[k] for k in ['SFARI_Category1','SFARI_Category1_2','Fu_ASD72','Fu_ASD185']});a['Walker2019_context']=walker(r);a['N_ASD_external_sources_supported']=r['N_ASD_external_sources_supported'];a['N_Huang_Matoba_Gandal_sources']=count(r)
 allrows.append(a)
allrows.sort(key=lambda r:(-r['N_ASD_external_sources_supported'],-int(r['JTI_FUSION_shared']),r['Gene']))
triple=[{k:r[k] for k in ['Gene','Ensembl_ID','JTI_significant','FUSION_significant','JTI_FUSION_shared','Huang2021_support','Matoba2020_support','Gandal2022_support']} for r in allrows if r['N_Huang_Matoba_Gandal_sources']==3]
summary=[{'Dataset':'JTI union FUSION vs '+r['external_study'],'TWAS genes':r['N_TWAS_set'],'External genes':r['N_external_set'],'Overlap number':r['N_overlap'],'Overlap genes':r['overlap_genes']} for r in ov]
for study,col in zip(['Huang','Matoba','Gandal'],cols):assert sum(bool(r[col]) for r in matrix)==next(r['N_overlap'] for r in ov if r['external_study']==study)
focus='MAPT-AS1 MAPT KANSL1-AS1 KANSL1 LRRC37A LRRC37A2 CRHR1 ARHGAP27 ARL17A NSF PLEKHM1 SPPL2C FAM215B DND1P1'.split()
regionrows=[]
for r in sorted(regional,key=lambda r:(focus.index(r['Gene']) if r['Gene'] in focus else 99,r['Gene'])):
 interpret='ASD genetic/transcriptomic convergence' if r[cols[0]] or count(r)>1 else 'ASD regulatory evidence' if r[cols[1]] else 'ASD molecular expression support' if r[cols[2]] else 'Developmental-brain context' if walker(r) else None
 status='JTI and FUSION significant' if r['JTI_FUSION_shared'] else 'JTI significant only' if r['JTI_significant'] else 'FUSION significant only' if r['FUSION_significant'] else 'Regional context; outside significant union'
 regionrows.append({'Gene':r['Gene'],'Ensembl_ID':r['Ensembl_ID'],'TWAS_status':status,'Huang2021':r[cols[0]],'Matoba2020':r[cols[1]],'Gandal2022':r[cols[2]],'Walker2019':walker(r),'Interpretation':interpret,'Gandal_tested':r['Gandal2022_tested'],'Gandal_region_secondary_support':r['Gandal2022_region_specific_support'],'Gandal_DIE_secondary_support':r['Gandal2022_DIE_support']})
assert set(focus)<=set(r['Gene'] for r in regionrows)
m=next(r for r in matrix if r['Gene']=='MAPT-AS1')
mt=[{'Gene':'MAPT-AS1','Ensembl_ID':m['Ensembl_ID'],'JTI_status':'Significant, all-tissue FDR < 0.05','FUSION_status':'Significant, all-tissue FDR < 0.05','Shared_status':m['JTI_FUSION_shared'],'Conditional/JT evidence':'Not recorded in the input benchmark workbook','Coloc status':'Not recorded in the input benchmark workbook','Huang2021':m[cols[0]],'Matoba2020':m[cols[1]],'Gandal2022':m[cols[2]],'Walker2019':'Prenatal expression TWAS / intracranial-volume context','SFARI':'Category 2; included in Categories 1-2, not Category 1','Fu':'No ASD72 or ASD185 overlap','JTI_min_FDR':m['JTI_min_FDR'],'FUSION_min_FDR':m['FUSION_min_FDR'],'Matoba_P':m['Matoba2020_P'],'Matoba_FDR':m['Matoba2020_FDR'],'Gandal_tested':m['Gandal2022_tested'],'Gandal_logFC':m['Gandal2022_logFC'],'Gandal_FDR':m['Gandal2022_FDR'],'Gandal_region_secondary_support':m['Gandal2022_region_specific_support'],'Gandal_DIE_secondary_support':m['Gandal2022_DIE_support'],'N_ASD_external_sources_supported':m['N_ASD_external_sources_supported']}]
dist=collections.Counter(count(r) for r in matrix);distribution=[{'Huang_Matoba_Gandal_sources':i,'N_genes':dist[i],'Fraction_of_152':dist[i]/152} for i in range(4)];assert sum(dist.values())==152
neutral='External evidence represents complementary support from different biological layers and should not be interpreted as independent replication unless explicitly supported by study design.'
notes=[('Purpose','Convergence summary of TWAS-prioritized genes and complementary external ASD genetic/transcriptomic evidence.'),('Input file',str(src)),('Input SHA256',digest),('Scope','Read existing benchmark results only. No new matching, external-study overlap analysis, FDR thresholds, literature search, enrichment, or manuscript changes.'),('Gene sets','JTI 64; FUSION 128; shared 40; union 152, retained from input workbook.'),('Huang2021','Family-based transcriptomic association. Input S1 meta-analysis also includes iPSYCH replication samples that overlap Grove 2019. Not fully independent.'),('Matoba2020','SPARK + prior GWAS meta-analysis with H-MAGMA brain regulatory mapping; partially independent cohort and orthogonal method.'),('Gandal2022','ASD postmortem cortex gene expression. Main support is whole-cortex idiopathic ASD gene-level DGE at source FDR < 0.05.'),('Triple convergence','Existing Huang, Matoba and Gandal main-support indicators all true among the 152 union genes.'),('Five-source count','N_ASD_external_sources_supported copied unchanged: SFARI, Fu, Huang, Matoba and Gandal, once per source. SFARI nested categories and Fu nested lists are not double-counted; Walker excluded.'),('Figure source count','N_Huang_Matoba_Gandal_sources counts only the three named literature benchmarks, range 0-3. It is distinct from the retained five-source count.'),('Sorting','Five-source count descending, then JTI/FUSION shared true first, then gene symbol alphabetically.'),('Walker','Prenatal expression or splicing evidence is developmental-brain / intracranial-volume context, not ASD support.'),('Regional interpretation','Huang support or at least two of the three ASD literature sources: ASD genetic/transcriptomic convergence. Matoba alone: ASD regulatory evidence. Gandal alone: ASD molecular expression support. Walker alone: Developmental-brain context. Blank when none of these labels is supported; SFARI/Fu remain available in the full table.'),('Regional secondary flags','Regional DGE and transcript DIE flags are retained descriptively and excluded from primary Gandal support and source counts.'),('MAPT-AS1 internal evidence','Conditional/joint and coloc results are absent from the input workbook. Marked as not recorded, which is not a negative finding. Other project files were not consulted.'),('Unresolved input','LOC441455 remains unresolved in the input Huang benchmark. Existing reported overlaps retained without attempting resolution.'),('Figures','Descriptive counts, not enrichment tests. Bar heights start at zero. Overlap bars are non-exclusive; one gene may occur in multiple sources. Distribution categories are exclusive and sum to 152.'),('Interpretation notes',neutral)]
tabs={'README':[{'Item':k,'Details':v} for k,v in notes],'Overlap_summary':summary,'Triple_convergence':triple or [{'Gene':None,'Status':'No genes supported by all three external sources'}],'ExternalEvidence_all_genes':allrows,'ExternalEvidence_17q21.31':regionrows,'MAPT_AS1_external_evidence':mt,'Support_distribution':distribution}
# Detailed lists are projections of existing support flags, with original statistics retained.
for label,col in zip(['Huang','Matoba','Gandal'],cols):tabs[label+'_overlap_genes']=[r for r in matrix if r[col]]
tabs['Figure_data']=[{'Figure':'Overlap','Category':r['external_study'],'N_genes':r['N_overlap']} for r in ov]+[{'Figure':'Support distribution','Category':str(i)+' sources','N_genes':dist[i]} for i in range(4)]
(W/'summary_tables.json').write_text(json.dumps(tabs,ensure_ascii=False,allow_nan=False),encoding='utf8')
paragraph=('MAPT-AS1 was prioritized by both JTI and FUSION in the existing all-tissue analysis. Its prioritization is supported by the Matoba et al. H-MAGMA gene set (FDR = '+format(m['Matoba2020_FDR'],'.6g')+') and by its inclusion in SFARI Categories 1-2 (Category 2). MAPT-AS1 did not overlap the Huang et al. significant meta-analysis gene set or the Fu ASD72/ASD185 sets. It was tested in the Gandal et al. whole-cortex ASD gene-level analysis but was not differentially expressed at the prespecified threshold (logFC = '+str(m['Gandal2022_logFC'])+', FDR = '+str(m['Gandal2022_FDR'])+'); the existing matrix also records no qualifying region-specific DGE or transcript-level DIE support. Walker et al. prenatal expression TWAS evidence provides developmental context for intracranial volume, rather than ASD replication. These findings describe complementary regulatory and curated support, with no qualifying postmortem expression support under the predefined criteria. Conditional/joint and colocalization findings are not recorded in the input benchmark workbook and cannot be assessed from this summary alone.')
(O/'MAPT-AS1 external evidence summary.txt').write_text('MAPT-AS1 external evidence summary\n\n'+paragraph+'\n\n'+neutral+'\n\nSource: '+str(src)+'\n',encoding='utf-8-sig')
report=['ASD External Evidence Convergence Report - 2026-09-26','', '1. Input',str(src),'SHA256: '+digest,'','2. Gene sets','JTI 64; FUSION 128; shared 40; union 152. Values retained from existing benchmark.','', '3-4. Overlaps and all gene lists']
for r in summary:report += [r['Dataset']+': '+str(r['Overlap number'])+'/'+str(r['TWAS genes'])+'; external set '+str(r['External genes']),r['Overlap genes'],'']
report+=['5. Triple convergence',', '.join(r['Gene'] for r in triple) if triple else 'None','', 'Three-source distribution: '+str(dict(sorted(dist.items()))),'', '6. 17q21.31 genes']
for r in regionrows:report.append(r['Gene']+' | '+r['TWAS_status']+' | Huang='+str(r['Huang2021'])+'; Matoba='+str(r['Matoba2020'])+'; Gandal='+str(r['Gandal2022'])+'; Walker='+str(r['Walker2019'])+' | Interpretation='+str(r['Interpretation'] or 'blank (no supported allowed label)'))
report+=['','7. MAPT-AS1 evidence',paragraph,'','Definitions and limitations']+[k+': '+v for k,v in notes[4:-1]]+['','Verification','Input workbook SHA256 retained. Counts reconciled to existing Overlap_summary and support flags; no original study files read.','', 'Interpretation notes',neutral]
(O/'ASD_External_Evidence_Convergence_Report_2026-09-26.txt').write_text('\n'.join(report),encoding='utf-8-sig')
print('Triple:',[r['Gene'] for r in triple]);print('Distribution:',dict(sorted(dist.items())));print('Tables:',{k:len(v) for k,v in tabs.items()})
